// G5b oracle: an INDEPENDENT implementation (Go's own sumdb `note` package, the reference the C2SP signed-note spec comes from)
// makes signed checkpoint notes and judges mutated ones. The Rust core must agree with it. note.go is NOT stored in the repo
// (BSD licence, lives in GOROOT); g5b-vectors.sh copies it into a temp dir at generation time.
// Output: JSON on stdout. Deterministic (fixed seeds), so the committed vectors file can be regenerated byte for byte.
package main

import (
	"g5b/note"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)


type key struct {
	Name   string `json:"name"`
	Seed   string `json:"seed_hex"`
	Pub    string `json:"pub_hex"`
	ID     string `json:"key_id_hex"`
	VKey   string `json:"vkey"`
	skey   string
	vkey   string
}

type vec struct {
	Key      int    `json:"key"`
	Size     uint64 `json:"size"`
	Root     string `json:"root_hex"`
	Note     string `json:"note"`
	GoVerify bool   `json:"go_verifies"`
}

type mut struct {
	Note     string `json:"note"`
	Why      string `json:"why"`
	Key      int    `json:"key"`
	GoVerify bool   `json:"go_verifies"`
}

func main() {
	var keys []key
	for i := 0; i < 4; i++ {
		seed := sha256.Sum256([]byte(fmt.Sprintf("g5b-vector-seed-%d", i)))
		priv := ed25519.NewKeyFromSeed(seed[:])
		pub := priv.Public().(ed25519.PublicKey)
		name := fmt.Sprintf("founderworkspace.anexomail.com/audit-log-%d", i)
		if i == 0 {
			name = "founderworkspace.anexomail.com/audit-log"
		}
		vkey, err := note.NewEd25519VerifierKey(name, pub)
		must(err)
		// skey: PRIVATE+KEY+name+hash+base64(0x01||seed); hash taken FROM Go's own vkey so it is Go's number, not ours
		parts := strings.SplitN(vkey, "+", 3)
		hash := parts[1]
		skey := fmt.Sprintf("PRIVATE+KEY+%s+%s+%s", name, hash, base64.StdEncoding.EncodeToString(append([]byte{1}, seed[:]...)))
		keys = append(keys, key{Name: name, Seed: hex.EncodeToString(seed[:]), Pub: hex.EncodeToString(pub), ID: hash, VKey: vkey, skey: skey, vkey: vkey})
	}
	sizes := []uint64{0, 1, 2, 3, 7, 29, 31, 50, 1000, 4294967296, 18446744073709551615}
	var vecs []vec
	for ki := range keys {
		s, err := note.NewSigner(keys[ki].skey)
		must(err)
		v, err := note.NewVerifier(keys[ki].vkey)
		must(err)
		for si, sz := range sizes {
			root := sha256.Sum256([]byte(fmt.Sprintf("root-%d-%d", ki, si)))
			text := fmt.Sprintf("%s\n%d\n%s\n", keys[ki].Name, sz, base64.StdEncoding.EncodeToString(root[:]))
			n, err := note.Sign(&note.Note{Text: text}, s)
			must(err)
			_, err = note.Open(n, note.VerifierList(v))
			vecs = append(vecs, vec{Key: ki, Size: sz, Root: hex.EncodeToString(root[:]), Note: string(n), GoVerify: err == nil})
		}
	}
	// mutations of one good note: every single-byte flip, judged by Go
	s0, _ := note.NewSigner(keys[0].skey)
	v0, _ := note.NewVerifier(keys[0].vkey)
	root := sha256.Sum256([]byte("mutation-base"))
	text := fmt.Sprintf("%s\n%d\n%s\n", keys[0].Name, 31, base64.StdEncoding.EncodeToString(root[:]))
	good, err := note.Sign(&note.Note{Text: text}, s0)
	must(err)
	var muts []mut
	for i := 0; i < len(good); i++ {
		b := append([]byte(nil), good...)
		b[i] ^= 0x01
		_, e := note.Open(b, note.VerifierList(v0))
		muts = append(muts, mut{Note: string(b), Why: fmt.Sprintf("flip byte %d", i), Key: 0, GoVerify: e == nil})
	}
	// structural cases, judged by Go
	add := func(why, n string) {
		_, e := note.Open([]byte(n), note.VerifierList(v0))
		muts = append(muts, mut{Note: n, Why: why, Key: 0, GoVerify: e == nil})
	}
	g := string(good)
	add("no trailing newline", strings.TrimSuffix(g, "\n"))
	add("CRLF", strings.ReplaceAll(g, "\n", "\r\n"))
	add("double blank line", strings.Replace(g, "\n\n", "\n\n\n", 1))
	add("two signature lines (same sig twice)", g+strings.Split(g, "\n\n")[1])
	add("tab in the text", strings.Replace(g, "audit-log\n", "audit\t-log\n", 1))
	add("empty", "")
	add("only text", strings.Split(g, "\n\n")[0]+"\n")
	// the published Go example
	pn, _ := note.NewVerifier("PeterNeumann+c74f20a3+ARpc2QcUPDhMQegwxbzhKqiBfsVkmqq/LDE4izWy10TW")
	pnNote := "If you think cryptography is the answer to your problem,\nthen you don't know what your problem is.\n\n— PeterNeumann x08go/ZJkuBS9UG/SffcvIAQxVBtiFupLLr8pAcElZInNIuGUgYN1FFYC2pZSNXgKvqfqdngotpRZb6KE6RyyBwJnAM=\n"
	_, e := note.Open([]byte(pnNote), note.VerifierList(pn))
	out := map[string]any{"keys": keys, "vectors": vecs, "mutations": muts,
		"published": map[string]any{"vkey": "PeterNeumann+c74f20a3+ARpc2QcUPDhMQegwxbzhKqiBfsVkmqq/LDE4izWy10TW", "note": pnNote, "go_verifies": e == nil}}
	b, _ := json.MarshalIndent(out, "", " ")
	os.Stdout.Write(b)
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
